CREATE TABLE IF NOT EXISTS chart_of_accounts(account_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT, ledger_code TEXT NOT NULL, ledger_name TEXT NOT NULL, account_type TEXT NOT NULL, parent_code TEXT, active INTEGER NOT NULL DEFAULT 1, UNIQUE(organization_id,entity_id,ledger_code));
CREATE TABLE IF NOT EXISTS journal_vouchers(journal_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, voucher_no TEXT NOT NULL, journal_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', narration TEXT, total_debit NUMERIC NOT NULL DEFAULT 0, total_credit NUMERIC NOT NULL DEFAULT 0, created_by TEXT NOT NULL, posted_by TEXT, posted_at TIMESTAMP, UNIQUE(organization_id,entity_id,voucher_no));
CREATE TABLE IF NOT EXISTS journal_voucher_lines(line_id TEXT PRIMARY KEY, journal_id TEXT NOT NULL, ledger_code TEXT NOT NULL, debit NUMERIC NOT NULL DEFAULT 0, credit NUMERIC NOT NULL DEFAULT 0, narration TEXT);
CREATE TABLE IF NOT EXISTS accounting_opening_balances(opening_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, ledger_code TEXT NOT NULL, debit NUMERIC NOT NULL DEFAULT 0, credit NUMERIC NOT NULL DEFAULT 0, created_by TEXT NOT NULL, UNIQUE(organization_id,entity_id,period_key,ledger_code));
CREATE TABLE IF NOT EXISTS financial_period_closes(close_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, period_key TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', closed_by TEXT, closed_at TIMESTAMP, reopened_by TEXT, reopened_at TIMESTAMP, reason TEXT, UNIQUE(organization_id,entity_id,period_key));
